import Head from 'next/head'
import fs from 'fs'
import path from 'path'
import Header from '../../components/Header'
import Footer from '../../components/Footer'
import SectionHeading from '../../components/SectionHeading'

const SITE_URL = 'https://anirbanbhk88.github.io'
const BLOG_TITLE = 'Blog — Anirban Bhowmick'
const BLOG_DESCRIPTION =
    'Notes and diary entries by Anirban Bhowmick — machine learning, engineering, and travel.'

/**
 * Reads data/posts.json (generated by scripts/build-posts.js). A missing or
 * empty manifest must NEVER break the build — try/catch with an empty list.
 */
function readAllPosts() {
    try {
        const manifestPath = path.join(process.cwd(), 'data', 'posts.json')
        const raw = fs.readFileSync(manifestPath, 'utf8')
        const manifest = JSON.parse(raw)
        return Array.isArray(manifest.posts) ? manifest.posts : []
    } catch (err) {
        return []
    }
}

export async function getStaticProps() {
    return {
        props: {
            posts: readAllPosts(),
        },
    }
}

function formatDate(iso) {
    try {
        return new Intl.DateTimeFormat('en-GB', {
            day: 'numeric',
            month: 'long',
            year: 'numeric',
        }).format(new Date(`${iso}T00:00:00`))
    } catch (e) {
        return iso
    }
}

/** Group posts by year (posts arrive date-desc), years sorted newest first. */
function groupByYear(posts) {
    const groups = new Map()
    for (const post of posts) {
        const year = (post.date || '').slice(0, 4) || 'Unknown'
        if (!groups.has(year)) groups.set(year, [])
        groups.get(year).push(post)
    }
    return [...groups.entries()].sort((a, b) => (a[0] < b[0] ? 1 : a[0] > b[0] ? -1 : 0))
}

export default function Blog({ posts = [] }) {
    const years = groupByYear(posts)

    return (
        <div className="min-h-screen">
            <Head>
                <title>{BLOG_TITLE}</title>
                <meta name="description" content={BLOG_DESCRIPTION} />

                <meta property="og:type" content="website" />
                <meta property="og:site_name" content="Anirban Bhowmick" />
                <meta property="og:title" content={BLOG_TITLE} />
                <meta property="og:description" content={BLOG_DESCRIPTION} />
                <meta property="og:url" content={`${SITE_URL}/blog/`} />
            </Head>

            <a href="#main" className="skip-link">
                Skip to content
            </a>

            <Header />

            <main id="main" className="mx-auto max-w-3xl px-4 py-16 sm:px-6 sm:py-20">
                <SectionHeading
                    align="left"
                    eyebrow="Writing"
                    title="Blog"
                    description="Occasional notes on machine learning, engineering, and journeys off the beaten track."
                />

                {posts.length === 0 ? (
                    <div className="mt-12 rounded-2xl border border-dashed border-slate-300 px-6 py-14 text-center dark:border-slate-700">
                        <svg
                            xmlns="http://www.w3.org/2000/svg"
                            fill="none"
                            viewBox="0 0 24 24"
                            strokeWidth="1.5"
                            stroke="currentColor"
                            className="mx-auto h-10 w-10 text-slate-400 dark:text-slate-500"
                            aria-hidden="true"
                        >
                            <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                d="M16.862 4.487l1.687-1.688a1.875 1.875 0 1 1 2.652 2.652L10.582 16.07a4.5 4.5 0 0 1-1.897 1.13L6 18l.8-2.685a4.5 4.5 0 0 1 1.13-1.897l8.932-8.931Zm0 0L19.5 7.125M18 14v4.75A2.25 2.25 0 0 1 15.75 21H5.25A2.25 2.25 0 0 1 3 18.75V8.25A2.25 2.25 0 0 1 5.25 6H10"
                            />
                        </svg>
                        <p className="mt-4 font-display text-lg font-semibold text-slate-900 dark:text-white">
                            No posts yet
                        </p>
                        <p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500 dark:text-slate-400">
                            Nothing has been published so far. Posts dropped into
                            <code className="mx-1 rounded bg-slate-100 px-1.5 py-0.5 text-xs dark:bg-slate-800">next-portfolio/public/posts/</code>
                            will appear here automatically.
                        </p>
                        <a
                            href="/"
                            className="mt-6 inline-block rounded-lg bg-primary-600 px-5 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-primary-700"
                        >
                            ← Back to Home
                        </a>
                    </div>
                ) : (
                    years.map(([year, yearPosts]) => (
                        <section key={year} aria-label={`Posts from ${year}`} className="mt-14">
                            <h2 className="font-display text-2xl font-bold text-slate-900 dark:text-white">
                                {year}
                            </h2>
                            <ul className="mt-6 space-y-6">
                                {yearPosts.map(post => (
                                    <li key={post.slug}>
                                        <article className="group rounded-2xl border border-slate-200 bg-white p-6 shadow-soft transition-all duration-300 hover:-translate-y-1 hover:shadow-lift dark:border-slate-800 dark:bg-slate-900">
                                            <div className="flex flex-wrap items-center gap-x-3 gap-y-2 text-xs text-slate-500 dark:text-slate-400">
                                                <time dateTime={post.date}>{formatDate(post.date)}</time>
                                                <span aria-hidden="true">·</span>
                                                <span>{post.author}</span>
                                                {post.tags && post.tags.length > 0 && (
                                                    <ul className="flex flex-wrap gap-1.5" aria-label="Tags">
                                                        {post.tags.map(tag => (
                                                            <li
                                                                key={tag}
                                                                className="rounded-full bg-primary-50 px-2.5 py-0.5 text-xs font-medium text-primary-700 dark:bg-primary-950/60 dark:text-primary-300"
                                                            >
                                                                {tag}
                                                            </li>
                                                        ))}
                                                    </ul>
                                                )}
                                            </div>

                                            <h3 className="mt-3 font-display text-xl font-semibold leading-snug text-slate-900 transition-colors group-hover:text-primary-700 dark:text-white dark:group-hover:text-primary-300">
                                                {/* Plain <a>: posts are static HTML files, not Next.js routes */}
                                                <a href={post.url}>{post.title}</a>
                                            </h3>

                                            {post.excerpt && (
                                                <p className="mt-2 text-sm leading-6 text-slate-600 dark:text-slate-400">
                                                    {post.excerpt}
                                                </p>
                                            )}

                                            <a
                                                href={post.url}
                                                className="mt-2 inline-flex items-center gap-1 py-2 -mb-2 text-sm font-semibold text-primary-600 transition-colors hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300"
                                                aria-label={`Read post: ${post.title}`}
                                            >
                                                Read post
                                                <span
                                                    aria-hidden="true"
                                                    className="transition-transform duration-300 group-hover:translate-x-0.5"
                                                >
                                                    →
                                                </span>
                                            </a>
                                        </article>
                                    </li>
                                ))}
                            </ul>
                        </section>
                    ))
                )}

                <div className="mt-14">
                    <a
                        href="/"
                        className="inline-flex items-center py-2 -my-2 text-sm font-semibold text-primary-600 transition-colors hover:text-primary-700 dark:text-primary-400 dark:hover:text-primary-300"
                    >
                        ← Back to Home
                    </a>
                </div>
            </main>

            <Footer />
        </div>
    )
}
